fun P odd even one =>
  WellFounded.Nat.fix (fun x => x.val) fun p a =>
    if h : p.val = 1 then ⋯ ▸ one
    else
      have hp := ⋯;
      let q := ⟨p.val / 2, ⋯⟩;
      if he : p.val % 2 = 0 then ⋯ ▸ even q (a q ⋯) else ⋯ ▸ odd q (a q ⋯)

fun d =>
  have x := NativeBridge.Incremental.DecimalRepresentation.trimHead d.reverse;
  (x.fst.reverse, x.snd)

fun d =>
  have x := NativeBridge.Incremental.DecimalRepresentation.trimTail d.snd;
  ((d.fst, x.fst), x.snd)

fun d =>
  have x := NativeBridge.Incremental.HexadecimalRepresentation.trimHead d.reverse;
  (x.fst.reverse, x.snd)

fun d =>
  have x := NativeBridge.Incremental.HexadecimalRepresentation.trimTail d.snd;
  ((d.fst, x.fst), x.snd)

fun b =>
  have v := { toFin := b };
  (v.getLsbD 0, v.getLsbD 1, v.getLsbD 2, v.getLsbD 3, v.getLsbD 4, v.getLsbD 5, v.getLsbD 6, v.getLsbD 7)

fun x y =>
  have z := BitVec.ofNat 63 (BitVec.toNat x + BitVec.toNat y + 1);
  if BitVec.toNat x + BitVec.toNat y + 1 < 2 ^ 63 then (false, z) else (true, z)

fun hi lo y =>
  if BitVec.toNat hi < BitVec.toNat y then
    have n := BitVec.toNat hi * 2 ^ 63 + BitVec.toNat lo;
    (BitVec.ofNat 63 (n / BitVec.toNat y), BitVec.ofNat 63 (n % BitVec.toNat y))
  else (0, 0)

fun s =>
  if s.snd.fst = true then some (if s.snd.snd = true then Ordering.gt else Ordering.eq)
  else if s.snd.snd = true then some Ordering.lt else none

fun prec emax sign m e l =>
  have first := NativeBridge.Incremental.SpecFloatShift.shiftToExponent prec emax m e l;
  have next :=
    NativeBridge.Incremental.SpecFloatRounding.nearestEven
      (NativeBridge.Incremental.SpecFloatRepresentation.mantissa first.fst)
      (NativeBridge.Incremental.SpecFloatRepresentation.fromShift first.fst);
  have second := NativeBridge.Incremental.SpecFloatShift.shiftToExponent prec emax next first.snd none;
  NativeBridge.Incremental.SpecFloatNormalize.finish sign
    (NativeBridge.Incremental.SpecFloatRepresentation.mantissa second.fst) second.snd (emax - prec)

fun x =>
  match x with
  | none => none
  | some (Sum.inr s) => if s = true then none else x
  | some (Sum.inl (s, fst, snd)) =>
    if NativeBridge.Incremental.PrimFloatRepresentation.isZero x = true then x
    else
      if s = true then none
      else
        have k :=
          ↑(NativeBridge.Incremental.PrimFloatRepresentation.mantissa x).log2 +
            NativeBridge.Incremental.PrimFloatRepresentation.exponent x;
        have q := max (-1074) (k / 2 - 52);
        have shift := NativeBridge.Incremental.PrimFloatRepresentation.exponent x - 2 * q;
        have n :=
          if shift < 0 then NativeBridge.Incremental.PrimFloatRepresentation.mantissa x
          else NativeBridge.Incremental.PrimFloatRepresentation.mantissa x * 2 ^ shift.toNat;
        have d := if shift < 0 then 2 ^ (-shift).toNat else 1;
        have m := (n / d).sqrt;
        have mid := d * (2 * m + 1) ^ 2;
        have m := if (decide (4 * n > mid) || 4 * n == mid && m % 2 == 1) = true then m + 1 else m;
        NativeBridge.Incremental.PrimFloatArithmetic.pack false m q

fun x =>
  have p := NativeBridge.Incremental.PrimFloatExponent.fractionShifted x;
  (p.fst, ↑p.snd.toNat - NativeBridge.Incremental.FloatOperations.exponentOffset)
